from fastmcp import FastMCP

mcp = FastMCP("notes-server")

@mcp.tool()
def search_notes(query: str, limit: int = 5) -> str:
    """Search saved notes for a matching keyword and return titles."""
    matches = [n.title for n in load_notes() if query.lower() in n.body.lower()]
    return "\n".join(matches[:limit])

if __name__ == "__main__":
    mcp.run()

from pydantic import BaseModel, Field

class TaskInput(BaseModel):
    title: str
    priority: int = Field(default=1, ge=1, le=5)

@mcp.tool()
def add_task(task: TaskInput) -> str:
    """Add a new task with a title and priority."""
    tasks.append(task)
    return f"Added task {task.title} at priority {task.priority}"

@mcp.resource("notes://all")
def all_notes() -> str:
    """Return every saved note as plain text."""
    return "\n\n".join(n.body for n in load_notes())

@mcp.resource("notes://{note_id}")
def one_note(note_id: str) -> str:
    """Return a single note by its id."""
    note = find_note(note_id)
    if note is None:
        raise ValueError(f"No note with id {note_id}")
    return note.body

@mcp.prompt()
def summarize_note(note_id: str) -> str:
    """Ask the model to summarize a note in two sentences."""
    note = find_note(note_id)
    return f"Summarize this note in two sentences:\n\n{note.body}"

@mcp.tool()
def delete_note(note_id: str) -> str:
    """Delete a note by its id."""
    if not note_exists(note_id):
        raise ValueError(f"No note found with id {note_id}")
    remove_note(note_id)
    return f"Deleted note {note_id}"

if __name__ == "__main__":
    mcp.run()               # stdio by default
