import { FastMCP } from "fastmcp";
import { z } from "zod";

const server = new FastMCP({ name: "notes-server", version: "1.0.0" });

server.addTool({
  name: "search_notes",
  description: "Search saved notes for a matching keyword",
  parameters: z.object({ query: z.string(), limit: z.number().default(5) }),
  execute: async ({ query, limit }) => {
    const matches = loadNotes().filter((n) => n.body.includes(query));
    return matches.slice(0, limit).map((n) => n.title).join("\n");
  }
});

server.start({ transportType: "stdio" });

from fastmcp import FastMCP

mcp = FastMCP("tasks-server")
tasks: list[str] = []

@mcp.tool()
def add_task(title: str) -> str:
    """Add a new task by title."""
    tasks.append(title)
    return f"Added as task #{len(tasks)}"

@mcp.resource("tasks://all")
def all_tasks() -> str:
    """Return every task as a numbered list."""
    return "\n".join(f"{i+1}. {t}" for i, t in enumerate(tasks))

@mcp.prompt()
def plan_my_day() -> str:
    """Ask the model to suggest an order for today's tasks."""
    return f"Suggest an order for:\n{chr(10).join(tasks)}"

if __name__ == "__main__":
    mcp.run()

from typing import Literal

@mcp.tool()
def convert_temp(value: float, to_unit: Literal["celsius", "fahrenheit"]) -> float:
    """Convert a temperature between celsius and fahrenheit."""
    if to_unit == "fahrenheit":
        return value * 9 / 5 + 32
    return (value - 32) * 5 / 9
